<?php
/**
 * Sports Betting demo content seeder — run via
 * `wp eval "require '/path/to/seed-sports-betting.php';"` (NOT `eval-file`,
 * which is known to silently no-op in this project's dev container — see
 * wp-cli/seed.php's own header comment and the project's
 * feedback_seed_php_batch_editing notes).
 *
 * Deliberately kept as its OWN file rather than appended to the 17MB
 * wp-cli/seed.php: that file is large enough that batch-editing it is its
 * own documented hazard (retry-limit / mid-block insertion / nowdoc-escaping
 * bug classes). This script defines its own `wwsb_`-prefixed helpers (never
 * `ww_`) so there is no function-redeclaration risk if it's ever run in the
 * same process as seed.php.
 *
 * Idempotent: every insert is matched by slug first, so re-running this is
 * safe and won't duplicate content or clobber manual edits.
 *
 * Seeds, across all 16 site languages (en/de/zh/es/pt/fr/it/sv/nb/fi/nl/ja/
 * pl/cs/ro/el):
 *   - The "Sports Betting" landing Page and its "Betting Guides" child Page.
 *   - A new `guide_category` term, "Sports Betting" (existing `guide` CPT is
 *     reused for Betting Guides, per the approved plan).
 *   - 3 sample `sportsbook` posts (bet365, Betway, Betsson) with concise,
 *     clearly-illustrative content — real, well-known, general facts (e.g.
 *     "MGA-licensed") but no invented license numbers or specific live
 *     offers. Meant as a populated starting point, not final editorial copy.
 *   - 1 sample `sportsbook_bonus` per sportsbook.
 *   - The one new nav string, "Sports Betting", as a Polylang UI string.
 */

defined( 'ABSPATH' ) || exit;

if ( function_exists( 'wagerwise_bootstrap_polylang_languages' ) ) {
	wagerwise_bootstrap_polylang_languages();
}

global $wwsb_refresh_content;
$wwsb_refresh_content = ! empty( getenv( 'WWSB_REFRESH_CONTENT' ) );

const WWSB_LANGS = array( 'en', 'de', 'zh', 'es', 'pt', 'fr', 'it', 'sv', 'nb', 'fi', 'nl', 'ja', 'pl', 'cs', 'ro', 'el' );

// -----------------------------------------------------------------------------
// Generic helpers (own prefix — deliberately not shared with seed.php's ww_*
// helpers, see file header).
// -----------------------------------------------------------------------------

/** Pick $lang's string from a {lang => text} map, falling back to English. */
function wwsb_t( array $map, string $lang ): string {
	return $map[ $lang ] ?? $map['en'];
}

function wwsb_seed_lang( int $object_id, string $type, string $lang ): void {
	if ( 'post' === $type && function_exists( 'pll_set_post_language' ) ) {
		pll_set_post_language( $object_id, $lang );
	} elseif ( 'term' === $type && function_exists( 'pll_set_term_language' ) ) {
		pll_set_term_language( $object_id, $lang );
	}
}

function wwsb_link_post_translations( array $ids ): void {
	if ( function_exists( 'pll_save_post_translations' ) && count( $ids ) > 1 ) {
		pll_save_post_translations( $ids );
	}
}

function wwsb_link_term_translations( array $ids ): void {
	if ( function_exists( 'pll_save_term_translations' ) && count( $ids ) > 1 ) {
		pll_save_term_translations( $ids );
	}
}

/** Mirrors seed.php's ww_seed_term() including its zero-width-space retry-limit fix (24 tries, exceeds the 16 supported languages). */
function wwsb_seed_term( string $taxonomy, string $name, string $lang ): int {
	$candidates = get_terms( array( 'taxonomy' => $taxonomy, 'name' => $name, 'hide_empty' => false ) );
	if ( ! is_wp_error( $candidates ) ) {
		foreach ( $candidates as $candidate ) {
			if ( ! function_exists( 'pll_get_term_language' ) || pll_get_term_language( $candidate->term_id ) === $lang ) {
				return (int) $candidate->term_id;
			}
		}
	}
	$attempt   = $name;
	$max_tries = 24;
	for ( $try = 0; $try < $max_tries; $try++ ) {
		$result = wp_insert_term( $attempt, $taxonomy );
		if ( ! is_wp_error( $result ) ) {
			$id = (int) $result['term_id'];
			wwsb_seed_lang( $id, 'term', $lang );
			return $id;
		}
		if ( 'term_exists' !== $result->get_error_code() && ! str_contains( $result->get_error_message(), 'already exists' ) ) {
			WP_CLI::warning( "Failed to create term '{$name}' in '{$taxonomy}': " . $result->get_error_message() );
			return 0;
		}
		$attempt = $name . str_repeat( "\xE2\x80\x8B", $try + 1 );
	}
	WP_CLI::warning( "Failed to create term '{$name}' in '{$taxonomy}' after {$max_tries} tries." );
	return 0;
}

/** Seeds one term per language from a {lang => name} map, links translations, returns {lang => term_id}. */
function wwsb_seed_term_i18n( string $taxonomy, array $names ): array {
	$ids = array();
	foreach ( $names as $lang => $name ) {
		$id = wwsb_seed_term( $taxonomy, $name, $lang );
		if ( $id ) {
			$ids[ $lang ] = $id;
		}
	}
	wwsb_link_term_translations( $ids );
	return $ids;
}

/** Mirrors seed.php's ww_seed_post(): matched by slug (language-independent), idempotent. */
function wwsb_seed_post( array $args, array $meta, string $lang ): int {
	$existing = get_posts( array(
		'post_type'      => $args['post_type'],
		'name'           => $args['post_name'] ?? '',
		'post_status'    => 'any',
		'posts_per_page' => 1,
		'fields'         => 'ids',
	) );

	if ( ! empty( $existing ) ) {
		$existing_id = (int) $existing[0];
		global $wwsb_refresh_content;
		if ( ! empty( $wwsb_refresh_content ) ) {
			// Re-assert the language tag before updating — if a slug ever
			// collides across languages despite the uniqueness discipline
			// above, this at least keeps the post's language correct (so a
			// mismatch is visibly wrong content in the wrong place) rather
			// than leaving it silently tagged as the FIRST language that
			// created the row, which makes Polylang's own
			// wp_insert_post_parent filter silently discard any post_parent
			// change that doesn't match that stale language's translation
			// group — confirmed the hard way once already.
			wwsb_seed_lang( $existing_id, 'post', $lang );
			$args['ID'] = $existing_id;
			wp_update_post( $args );
			foreach ( $meta as $key => $value ) {
				update_post_meta( $existing_id, $key, $value );
			}
		}
		return $existing_id;
	}

	$post_id = wp_insert_post( $args );
	if ( is_wp_error( $post_id ) || ! $post_id ) {
		return 0;
	}

	// Language must be set before anything else touches this post, matching
	// seed.php's own documented ordering lesson (Polylang's term-assignment
	// hook otherwise defaults to the site's default language).
	wwsb_seed_lang( $post_id, 'post', $lang );

	foreach ( $meta as $key => $value ) {
		update_post_meta( $post_id, $key, $value );
	}

	return $post_id;
}

/** Seeds the same logical post in every language from a {lang => [args, meta]} map, links translations. */
function wwsb_seed_post_i18n( array $per_lang ): array {
	$ids = array();
	foreach ( $per_lang as $lang => $spec ) {
		$id = wwsb_seed_post( $spec['args'], $spec['meta'] ?? array(), $lang );
		if ( $id ) {
			$ids[ $lang ] = $id;
		}
	}
	wwsb_link_post_translations( $ids );
	return $ids;
}

