foreach ( $sportsbooks as $key => $sb ) {
	$per_lang_ids = array();

	foreach ( WWSB_LANGS as $lang ) {
		$pros = array_map( fn( $k ) => wwsb_t( $PROS_BANK[ $k ], $lang ), $sb['pros'] );
		$cons = array_map( fn( $k ) => wwsb_t( $CONS_BANK[ $k ], $lang ), $sb['cons'] );
		$sports = array_map( fn( $k ) => wwsb_t( $SPORTS_BANK[ $k ], $lang ), $sb['sports'] );
		$payments = array_map( fn( $p ) => is_array( $p ) ? wwsb_t( $p, $lang ) : $p, $sb['payments'] );

		// Structured, multi-section review body — mirrors the real casino
		// reviews' H2-sectioned format (see seed.php's LeoVegas review:
		// Licensing & Regulation, Payment Methods, Mobile Experience,
		// Customer Support, Final Verdict, etc.) rather than a two-sentence
		// blurb, so a "Read Review" click lands on a genuinely informative
		// page. Brand-specific facts (legitimacy/licensing) come from each
		// sportsbook's own entry; the rest are shared templates (%s = name).
		$h = fn( string $key ) => wwsb_t( $REVIEW_HEADINGS[ $key ], $lang );
		$t = fn( string $key ) => wwsb_t( $REVIEW_TEXT[ $key ], $lang );
		$review_body = sprintf(
			'<h2>%1$s</h2><p>%2$s</p>' .
			'<h2>%3$s</h2><p>%4$s</p>' .
			'<h2>%5$s</h2><p>%6$s</p>' .
			'<h2>%7$s</h2><p>%8$s</p>' .
			'<h2>%9$s</h2><p>%10$s</p>' .
			'<h2>%11$s</h2><p>%12$s</p>' .
			'<h2>%13$s</h2><p>%14$s</p>' .
			'<h2>%15$s</h2><p>%16$s</p>' .
			'<h2>%17$s</h2><p>%18$s</p>' .
			'<p><em>%19$s</em></p>',
			sprintf( $h( 'legitimacy' ), esc_html( $sb['title'] ) ), esc_html( wwsb_t( $sb['legitimacy'], $lang ) ),
			$h( 'licensing' ), esc_html( wwsb_t( $sb['licensing'], $lang ) ),
			$h( 'markets' ), esc_html( sprintf( $t( 'markets' ), $sb['title'] ) ),
			$h( 'live' ), esc_html( $t( 'live' ) ),
			$h( 'payments' ), esc_html( $t( 'payments' ) ),
			$h( 'mobile' ), esc_html( $t( 'mobile' ) ),
			$h( 'support' ), esc_html( $t( 'support' ) ),
			sprintf( $h( 'who_for' ), esc_html( $sb['title'] ) ), esc_html( sprintf( $t( 'who_for' ), $sb['title'] ) ),
			$h( 'verdict' ), esc_html( sprintf( $t( 'verdict' ), $sb['title'] ) ),
			esc_html( wwsb_t( $SAMPLE_NOTE, $lang ) )
		);

		$args = array(
			'post_type'    => 'sportsbook',
			'post_title'   => $sb['title'],
			// Same brand-name slug across every language (a proper noun, not
			// translated) — per seed.php's documented lesson, non-English
			// languages need a language-suffixed slug or ww_seed_post()'s
			// slug-only match will silently collapse them onto the English post.
			'post_name'    => 'en' === $lang ? $sb['slug'] : $sb['slug'] . '-' . $lang,
			'post_content' => $review_body,
			'post_excerpt' => wwsb_t( $sb['description'], $lang ),
			'post_status'  => 'publish',
		);

		$meta = array(
			'ww_rating'            => $sb['rating'],
			'ww_short_description' => wwsb_t( $sb['description'], $lang ),
			'ww_bonus_value'       => wwsb_t( $sb['bonus'], $lang ),
			'ww_pros'              => $pros,
			'ww_cons'              => $cons,
			'ww_payment_methods'   => $payments,
			'ww_sports_available'  => $sports,
			'ww_license'           => $sb['license'],
			// Placeholder — no real affiliate program is wired up yet; replace
			// with the actual tracked affiliate link before going live.
			'ww_affiliate_link'    => 'https://example.com/go/' . $sb['slug'],
			'ww_terms_url'         => 'https://example.com/terms/' . $sb['slug'],
			'ww_cta_label'         => wwsb_t( $VISIT_SITE, $lang ),
		);

		$id = wwsb_seed_post( $args, $meta, $lang );
		if ( $id ) {
			$per_lang_ids[ $lang ] = $id;
		}
	}

	wwsb_link_post_translations( $per_lang_ids );

	// One sample bonus per sportsbook, linked to that same language's post.
	$bonus_ids = array();
	foreach ( $per_lang_ids as $lang => $sportsbook_id ) {
		$bonus_args = array(
			'post_type'    => 'sportsbook_bonus',
			'post_title'   => sprintf( '%s %s', $sportsbooks[ $key ]['title'], wwsb_t( array( 'en' => 'Welcome Bonus', 'de' => 'Willkommensbonus', 'zh' => '欢迎红利', 'es' => 'Bono de Bienvenida', 'pt' => 'Bónus de Boas-Vindas', 'fr' => 'Bonus de Bienvenue', 'it' => 'Bonus di Benvenuto', 'sv' => 'Välkomstbonus', 'nb' => 'Velkomstbonus', 'fi' => 'Tervetuliaisbonus', 'nl' => 'Welkomstbonus', 'ja' => 'ウェルカムボーナス', 'pl' => 'Bonus Powitalny', 'cs' => 'Uvítací Bonus', 'ro' => 'Bonus de Bun Venit', 'el' => 'Μπόνους Καλωσορίσματος' ), $lang ) ),
			'post_name'    => ( 'en' === $lang ? $key : $key . '-' . $lang ) . '-bonus',
			'post_content' => '',
			'post_status'  => 'publish',
		);
		$bonus_meta = array(
			'ww_related_sportsbook' => $sportsbook_id,
			'ww_bonus_value'        => wwsb_t( $sportsbooks[ $key ]['bonus'], $lang ),
			'ww_affiliate_link'     => 'https://example.com/go/' . $key,
			'ww_cta_label'          => wwsb_t( $CLAIM_BONUS, $lang ),
		);
		$bonus_id = wwsb_seed_post( $bonus_args, $bonus_meta, $lang );
		if ( $bonus_id ) {
			$bonus_ids[ $lang ] = $bonus_id;
		}
	}
	wwsb_link_post_translations( $bonus_ids );
}

