		$language = function_exists( 'PLL' ) ? PLL()->model->get_language( $lang_slug ) : null;
		if ( ! $language ) {
			continue;
		}
		$mo = new PLL_MO();
		$mo->import_from_db( $language );
		foreach ( $ui_strings as $en_string => $translations ) {
			if ( ! empty( $translations[ $lang_slug ] ) ) {
				$mo->add_entry( $mo->make_entry( $en_string, $translations[ $lang_slug ] ) );
			}
		}
		$mo->export_to_db( $language );
	}
}

// -----------------------------------------------------------------------------
// Rank Math sitemap opt-in for the 2 new post types — mirrors the existing
// idempotent block seed.php already runs for every other CasinoRadar CPT
// (Rank Math only auto-includes post types it knew about at its own
// activation time, so custom ones registered later are otherwise silently
// absent from the sitemap).
// -----------------------------------------------------------------------------

if ( function_exists( 'update_option' ) ) {
	$rankmath_sitemap_opt = get_option( 'rank-math-options-sitemap', array() );
	foreach ( array( 'sportsbook', 'sportsbook_bonus' ) as $pt ) {
		$rankmath_sitemap_opt[ 'pt_' . $pt . '_sitemap' ] = 'on';
	}
	update_option( 'rank-math-options-sitemap', $rankmath_sitemap_opt );
}

if ( class_exists( 'WP_CLI' ) ) {
	WP_CLI::success( 'Sports Betting demo content seeded (pages, guide_category term, 3 sportsbooks + bonuses, nav string) across ' . count( WWSB_LANGS ) . ' languages.' );
}
